/* SPDX-License-Identifier: MIT */
/* tan: the MPFR sweep pieces, the design's named points, the BaCSeL hard cases and the
 * pole windows, in the shape of sweep/fns/exp2_exact.c.
 *
 * eval is fixTanExact. ref is MPFR 256-bit tan( raw * 2^-16 ), rounded to Q48.16 by
 * sweep_mpfr_round. The function saturates to +/-INT64_MAX (never INT64_MIN) where
 * |tan * 2^16| >= 2^63 - 3/2, so ref applies the same rule before rounding; a plain
 * sweep_mpfr_round would return INT64_MIN on the negative poles.
 *
 * The pieces are:
 *   - every raw with |raw| < 2^21 (|x| < 32 rad), 4,194,303 inputs, exhaustive;
 *   - 2^18 seeded raws per binade from 2^21 to 2^63, SWEEP_PER_BINADE;
 *   - every raw within 64 of each positive multiple of pi/2 up to 2^20 rad, as POINTS
 *     (the pole windows, one list of 86,113,305 points; sweep_point is 16 bytes, so the
 *     list is held in .bss and filled by a constructor);
 *   - every case of test/data/hardcases/tan_big.txt (BaCSeL, 7936 raws) as points in the
 *     same static descriptor array, copied from the committed list at construction;
 *   - the named points of docs/design/transcendentals.md section 3.1, signed, plus both
 *     sides of pi/4 and of 1/256;
 *   - the libfixmath edge list.
 *
 * The pole window centres use A = round( pi/2 * 2^32 ) = 6746518852, so the window's
 * centre raw is ( m * A ) >> 16 and is within 5.1 raw of the exact multiple for every
 * m <= 667544, far inside the required 64. Negative angles are covered by exact oddness
 * and by the signed exhaustive and named pieces.
 */
#include "../sweep.h"
#include "../data/libfixmath_edges.h"
#include "fixed/fixed_tan.h"

#define TAN_NAMED_COUNT 35
#define TAN_HARD_COUNT 7936
#define TAN_POLE_M_MAX 667544
#define TAN_POLE_POINT_COUNT ( ( TAN_POLE_M_MAX + 1 ) * 129 )
#define TAN_POINT_COUNT ( TAN_NAMED_COUNT + TAN_HARD_COUNT + TAN_POLE_POINT_COUNT )

static mpfr_t* tan_limit( void )
{
	static __thread mpfr_t v;
	static __thread int ready = 0;
	if ( !ready )
	{
		mpfr_init2( v, 256 );
		/* ( 2^64 - 3 ) / 2^17 = 2^47 - 3/2^17 = ( 2^63 - 3/2 ) / 2^16 */
		mpfr_set_ui( v, (unsigned long)( ~(uint64_t)0 - 2 ), MPFR_RNDN );
		mpfr_div_2ui( v, v, 17, MPFR_RNDN );
		ready = 1;
	}
	return &v;
}

static int64_t eval( int64_t a, int64_t b )
{
	( void )b;
	return fixTanExact( a );
}

static int64_t ref( int64_t a, int64_t b )
{
	( void )b;
	mpfr_t* v = sweep_mpfr_tmp();
	mpfr_set_si( *v, (long)a, MPFR_RNDN );
	mpfr_div_2ui( *v, *v, 16, MPFR_RNDN );
	mpfr_tan( *v, *v, MPFR_RNDN );
	if ( mpfr_cmpabs( *v, *tan_limit() ) >= 0 )
	{
		return mpfr_sgn( *v ) < 0 ? -INT64_MAX : INT64_MAX;
	}
	return sweep_mpfr_round( *v );
}

static const sweep_piece pieces[] = {
	{ -2097151, 2097152, 0, 0, 0, SWEEP_EXHAUSTIVE },
	{ 2097152, INT64_MAX, 0, 0, 262144, SWEEP_PER_BINADE },
};

